"""Figures and descriptive findings, retaining individual source seeds."""
from audit import *
import pandas as pd,numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def main():
 cfg=json.loads((O/'analysis_config.json').read_text());F=O/'figures';F.mkdir(exist_ok=True)
 rank=pd.read_csv(O/'rank_stability.csv');late=pd.read_csv(O/'late_rising_weight_summary.csv');transition=pd.read_csv(O/'rank_transition_summary.csv');metrics=pd.read_csv(O/'expert_interval_metrics.csv');prediction=pd.read_csv(O/'held_out_prediction_results.csv');ass=pd.read_csv(O/'seed_association_summaries.csv');surv=pd.read_csv(O/'realized_survivor_fractions.csv');pers=pd.read_csv(O/'rank_persistence.csv')
 def savefig(name):plt.tight_layout();plt.savefig(F/(name+'.png'),dpi=160);plt.savefig(F/(name+'.pdf'));plt.close()
 adj=set(map(tuple,zip(cfg['checkpoint_steps'][:-1],cfg['checkpoint_steps'][1:])))
 r=rank[[tuple(x) in adj for x in rank[['start_step','end_step']].to_numpy()]]
 fig,axes=plt.subplots(1,3,figsize=(13,3.7))
 for ax,unit in zip(axes,['fc1','fc2','joint']):
  for seed,g in r[r.tensor==unit].groupby('seed'):
   v=g.groupby('end_step').rank_correlation.mean();ax.plot(v.index,v.values,marker='o',label=str(seed))
  ax.set(title=unit,xlabel='Checkpoint pair (attempted steps)',ylabel='Mean expert rank correlation');ax.set_xticks([250,500,1000,1750,2500],['0–250','250–500','500–1000','1000–1750','1750–2500'],rotation=25,fontsize=7);ax.legend(title='Source seed',fontsize=7)
 savefig('rank_stability_individual_seeds')
 fig,axes=plt.subplots(1,5,figsize=(15,3.3));sel=transition[(transition.tensor=='joint')&(transition.start_step==250)&(transition.end_step==2500)]
 for ax,(seed,g) in zip(axes,sel.groupby('seed')):
  m=g.groupby(['early_bin','late_bin'])['count'].sum().unstack().to_numpy();m=m/m.sum(1,keepdims=True);im=ax.imshow(m,vmin=0,vmax=1,cmap='Blues');ax.set(title=f'Seed {seed}',xlabel='Late quintile',ylabel='Step250 quintile');ax.set_xticks(range(5),range(1,6));ax.set_yticks(range(5),range(1,6))
  for i in range(5):
   for j in range(5):ax.text(j,i,f'{m[i,j]:.2f}',ha='center',va='center',fontsize=7,color='white' if m[i,j]>.5 else 'black')
 savefig('rank_transition_matrices')
 fig,axes=plt.subplots(1,2,figsize=(11,4))
 for ax,f in zip(axes,[.2,.15]):
  z=late[(late.tensor=='joint')&(late.retained_fraction==f)&(late.end_step==2500)&(late.start_step>0)]
  for seed,g in z.groupby('seed'):
   v=g.groupby('start_step').fraction_later_top_removed.mean();ax.plot(v.index,v.values,marker='o',label=str(seed))
  ax.set(title=f'Hypothetical {round((1-f)*100)}% early pruning',xlabel='Early checkpoint',ylabel='Fraction of step2500 top weights omitted');ax.legend(title='Source seed',fontsize=7)
 savefig('retrospective_pruning_disagreements')
 fig,axes=plt.subplots(4,3,figsize=(12,11),sharex=True,sharey=True)
 z=metrics[(metrics.tensor=='joint')&metrics.apply(lambda x:(x.start_step,x.end_step) in adj,axis=1)]
 for l in range(4):
  for ax,(t,u) in zip(axes[l],[(500,1000),(1000,1750),(1750,2500)]):
   for seed,g in z[(z.layer==l)&(z.start_step==t)&(z.end_step==u)].groupby('seed'):ax.scatter(g.prior_log_rate_change,g.late_rising_fraction,s=10,alpha=.6,label=str(seed))
   ax.set(title=f'Layer{l}, outcome {t}–{u}',xlabel='Prior log accepted-rate change',ylabel='Subsequent early-low → top20 fraction')
 axes[0,0].legend(title='Seed',fontsize=6);savefig('past_exposure_subsequent_turnover_stratified')
 plt.figure(figsize=(7,4));plt.bar(prediction.held_out_seed.astype(str),prediction.relative_mse_improvement*100);plt.axhline(0,color='black',lw=1);plt.xlabel('Held-out source seed');plt.ylabel('MSE reduction from exposure features (%)');savefig('incremental_held_out_prediction')
 lines=['# Exploratory expert exposure and weight development','','This retrospective analysis uses all five compatible original, unpruned 32E source trajectories. Cohort/grid/features were frozen after the coverage audit and before outcome associations. No training, recovery, IMP, pruning sweep, or new model forward/backward was run. Historical artifacts remain untouched.','', '## Individual-seed rank results','','Primary joint fc1+fc2 ranks, step250 → step2500. Low means bottom50%; late-high means top20%. These are exact coordinate counts, not sampled coordinates.','', '| Source seed | Rank correlation | Early-low → late-top fraction | Later top20 omitted by hypothetical early80% pruning | Absolute magnitude change among late risers |','|---|---:|---:|---:|---:|']
 for seed in cfg['source_seeds']:
  a=rank[(rank.seed==seed)&(rank.tensor=='joint')&(rank.start_step==250)&(rank.end_step==2500)];b=late[(late.seed==seed)&(late.tensor=='joint')&(late.start_step==250)&(late.end_step==2500)&(late.retained_fraction==.2)]
  lines.append(f'| {seed} | {a.rank_correlation.mean():.6f} | {b.late_rising_fraction_of_early_low.mean():.8f} | {b.fraction_later_top_removed.mean():.6f} | {b.late_riser_mean_abs_change.mean():.8f} |')
 lines+=['','Top15 sensitivity, within-tensor ranks, every expert/layer/interval, transition matrices, persistence and continuous rank changes are in the CSVs. Initialization step0 is explicitly flagged and excluded from the primary early-low interpretation. Additional early checkpoints for only three seeds are not substituted into five-seed comparisons.','', '## Stabilization across observed intervals','']
 for unit in ['fc1','fc2','joint']:
  lines.append(f'{unit}:')
  for (t,u),g in r[(r.tensor==unit)&(r.start_step>0)].groupby(['start_step','end_step']):
   means=g.groupby('seed').rank_correlation.mean();turn=g.groupby('seed').top20_turnover.mean();lines.append(f'- {t}–{u}: seed-mean rank correlation range {means.min():.6f}–{means.max():.6f}; top20 turnover range {turn.min():.6f}–{turn.max():.6f}.')
 lines+=['','Unequal interval lengths and update counts are explicit in expert_interval_metrics.csv; raw stability should not be compared as an equal-horizon learning rate. There is no unique stabilization time inferred between checkpoints. The earliest common nonzero checkpoint is250; behavior before that is limited.','', '## Exposure association and prediction','', 'Quantity counts cover every attempted step and distinguish proposed, accepted, dropped, applied-update accepted exposure and skipped-update exposure. The probe feature is proposed-membership Jaccard turnover on saved validation routing. Accepted training-token composition, contextual hidden inputs, gate-weighted exposure, and genuine domain distributions are unavailable. Biased first-two context snippets are not treated as composition measurements.','', 'Descriptive correlations compare experts within seed/layer/interval/ranking. Source seed is the replication unit. Same-interval correlations describe co-development, while predictive features stop at the outcome start. Every source seed is held out with all of its experts and intervals. One Ridge(alpha=1) model, train-only preprocessing, fixed features, and adjacent outcomes were used; no model/hyperparameter search.','', '| Held-out seed | Outcome mean | Baseline MSE | Exposure MSE | Relative MSE reduction |','|---|---:|---:|---:|---:|']
 for a in prediction.to_dict('records'):lines.append(f"| {a['held_out_seed']} | {a['held_out_outcome_mean']:.8f} | {a['baseline_mse']:.9g} | {a['extension_mse']:.9g} | {a['relative_mse_improvement']:.3%} |")
 initial=rank[rank.start_step==0].groupby(['seed','layer','tensor']).agg(mean_initial_abs=('initial_mean_absolute_magnitude','mean'),minimum_expert_initial_abs=('initial_mean_absolute_magnitude','min'),maximum_expert_initial_abs=('initial_mean_absolute_magnitude','max')).reset_index()
 initial.to_csv(O/'initialization_scale_summary.csv',index=False)
 positive=int((prediction.mse_improvement>0).sum());lines += ['',f'Exposure improves held-out MSE in {positive}/5 source seeds. Mean relative MSE reduction: {prediction.relative_mse_improvement.mean():.3%}; range {prediction.relative_mse_improvement.min():.3%}–{prediction.relative_mse_improvement.max():.3%}. No source-seed significance or causal claim is made. The changing outcome base rate and seed-mean null MSE are reported explicitly.','', 'Per-seed mean stratified Spearman associations with subsequent rank rise:','']
 for feature in ['prior_log_applied_rate','prior_log_rate_change','prior_probe_turnover']:
  z=ass[(ass['mode']=='past_exposure_subsequent_outcome')&(ass.feature==feature)];lines.append('- '+feature+': '+', '.join(f"seed{int(a['seed'])}={a['mean']:.4f}" for a in z.to_dict('records')))
 lines += ['', '## Alternative explanations and limits','', 'Initialization_scale_summary.csv records observed initialization magnitudes by seed/layer/projection. The model uses PyTorch Linear initialization: fc1 has fan-in256 and fc2 fan-in1024, so their initial uniform bounds differ by a factor of2. Joint ranking therefore starts with different projection scales; within-tensor results help distinguish this from development. Initial mean absolute magnitude/initialization scale, current mean/low-half magnitude, prior magnitude-growth rate, prior late-rising fraction, prior top-set turnover, layer/tensor identity, global progress, interval duration, and prior applied-update count enter the baseline. fc1/fc2 and layers are reported separately; low/high prior utilization is compared within strata in utilization_strata.csv. Experts share exposure across coordinates: millions of weights are never treated as independent exposure replications. Expert IDs are not matched across seeds.','', 'Both projections are pooled for the actual expert-local pruning budget. realized_survivor_fractions.csv shows the realized allocation by projection; nominal80/85% expert sparsity is not imposed independently on fc1/fc2. Repository torch.topk has unspecified boundary tie membership; exact counts and all tied-boundary membership discrepancies are audited against the deterministic ordinal convention.','']
 for (f,pn),g in surv.assign(projection=surv.parameter_name.str.extract(r'\.(fc[12])\.')[0]).groupby(['retained_fraction','projection']):lines.append(f'- Joint retained{f:.2f}, {pn}: realized tensor survivor fraction range {g.survivor_fraction.min():.6f}–{g.survivor_fraction.max():.6f}.')
 lines += ['', 'The primary source trajectory has no interior optimizer reset. Recovery resets at absolute2500 and IMP discovery rounds are inventoried as distinct excluded protocols. Weight decay was AdamW0.01; absent optimizer states prevent isolating its contribution from gradients. Applied-update/AMP differences are retained. Fixed-probe changes may reflect shared-network learning as well as router development.','', 'coordinate_examples.csv rereads exact named coordinates and illustrates rank rise with absolute growth versus rank rise without growth. These are illustrative outcome-selected examples, not independent evidence. Rank rise can result from other weights shrinking. Magnitude, late growth, and hypothetical mask membership do not establish functional importance. No final IMP mask is used as useful-weight ground truth.','', 'An expert-level signal could identify unstable experts without identifying which coordinates to prune. Associations cannot establish the direction of causation. The eventual criterion is improved task loss/recovery after actual pruning, which this retrospective analysis does not measure.','', '## Required verdict','', 'See the reviewed verdict below. All findings concern observed checkpoints and quantities; the missing historical input-composition measurements preclude a direct composition mechanism test.']
 primary=late[(late.tensor=='joint')&(late.start_step==250)&(late.end_step==2500)&(late.retained_fraction==.2)].groupby('seed').late_rising_fraction_of_early_low.mean()
 lines += ['', '**Reviewed verdict: Available data is insufficient.**', '', 'This verdict concerns evidence for a routing-aware pruning experiment, not coverage for the descriptive analysis. The five compatible source trajectories support exact rank description and a small held-out expert-level predictive comparison. They do not establish a useful coordinate-selection rule or a practically meaningful loss/recovery benefit. The exposure extension improves MSE in all five seeds, but two improvements are below0.4%, and their importance for pruning is unknown. No prospective expansion is recommended or launched from this first pass.', '', '1. **Do early magnitude ranks stabilize, and when?** No clear stabilization checkpoint is established. Ranks retain substantial structure but remain mobile through2500. In the two equal750-attempt late intervals, joint top20 turnover averages about15.48% and15.46%, respectively. Higher correlations over shorter horizons are not proof that learning has stabilized.', f'2. **How often do early-low weights become large?** For step250 bottom-half to step2500 top20 joint ranks, the per-seed expert-mean fraction is {primary.min():.2%}–{primary.max():.2%}. Within-tensor and top15 sensitivity results are reported separately. Absolute growth accompanies the primary late risers; rank rise alone is not treated as growth or usefulness.', '3. **Exposure quantity, composition, both, or neither?** Same-interval changes in accepted rate have positive mean stratified associations in all five seeds (roughly0.15–0.25 Spearman); drop fraction also has positive same-interval associations. These are descriptive and can reflect confounding. Past accepted rate has negative mean associations with subsequent rise, while rate-change and fixed-probe associations are weak/mixed. Historical accepted contextual composition is unrecorded, so a composition mechanism is unanswerable; proposed fixed-probe membership is only a limited surrogate.', f'4. **Does exposure add information beyond current magnitude and prior growth?** A small observed increment: relative held-out MSE reduction averages {prediction.relative_mse_improvement.mean():.2%}, range {prediction.relative_mse_improvement.min():.2%}–{prediction.relative_mse_improvement.max():.2%}, with5/5 positive signs. This is one fixed expert-level model and does not identify which individual coordinates to remove. It does not establish a robust functional pruning advantage.', '5. **Which conclusions are coverage-limited?** Before the earliest common nonzero checkpoint250, between sparse checkpoints, and beyond2500, five-seed dynamics are unresolved. Accepted token-ID/context distributions, hidden inputs, gate-weighted exposure, domain labels, and optimizer states are absent. Weight-decay mechanisms and causal direction cannot be isolated. Probe identity is supported by common data/configuration and batch shapes; the archived assignment files do not contain token hashes.', '6. **Enough evidence for a prospective pruning experiment?** Not from this bounded pass alone. The result is a modest ranking-instability forecast without a validated pruning decision or task-level endpoint. No prospective comparison is implemented or launched. The eventual standard remains matched-sparsity, matched-budget loss/recovery improvement after actual pruning.']
 text='\n'.join(lines)+'\n'
 for before,after in {'below0.4%':'below 0.4%', 'through2500':'through step 2500', 'equal750-attempt':'equal 750-attempt', 'top20':'top 20%', 'top15':'top 15%', 'step2500':'step 2500', 'step250':'step 250', 'roughly0.15':'roughly 0.15', 'with5/5':'with 5/5', 'checkpoint250':'checkpoint 250', 'beyond2500':'beyond step 2500', 'fan-in256':'fan-in 256', 'fan-in1024':'fan-in 1024', 'of2.':'of 2.', 'nominal80/85%':'nominal 80/85%', 'AdamW0.01':'AdamW 0.01', 'absolute2500':'absolute step 2500'}.items():text=text.replace(before,after)
 (O/'findings.md').write_text(text)
if __name__=='__main__':main()
